// Title: How to render Unicode supplementary characters (e.g., emojis) in a PDF generated by Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# render emoji in PDF output | verify Unicode supplementary character display after saving workbook as PDF with Aspose.Cells | increase font size for emoji in Excel cell before PDF conversion using Aspose.Cells | troubleshoot missing emoji in PDF generated from Excel with Aspose.Cells .NET | save workbook as PDF with Unicode emoji using Aspose.Cells API
// Tags: emoji rendering in Aspose.Cells PDF export | Unicode supplementary character support in PDF conversion | set cell font size for emoji Aspose.Cells | Aspose.Cells PDF export Unicode handling | C# Aspose.Cells PDF Unicode verification

using System;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// The example creates a workbook, inserts an emoji (U+1F600) into cell A1, applies a larger font size, saves the workbook as a PDF, and instructs the user to open the file to confirm that the emoji renders correctly in the PDF output.
class UnicodePdfVerification
{
    static void Main()
    {
        // Create a new workbook
        Workbook workbook = new Workbook();

        // Access the first worksheet
        Worksheet sheet = workbook.Worksheets[0];

        // Insert a Unicode supplementary character (emoji) into cell A1
        // Example emoji: Grinning Face 😀 (U+1F600)
        sheet.Cells["A1"].PutValue("😀");

        // Optionally set a larger font size to make the emoji more visible
        Style style = workbook.CreateStyle();
        style.Font.Size = 24;
        sheet.Cells["A1"].SetStyle(style);

        // Save the workbook as PDF
        // The PDF will contain the emoji character rendered in the cell
        string pdfPath = "UnicodeEmojiOutput.pdf";
        workbook.Save(pdfPath, SaveFormat.Pdf);

        // At this point, manually open the generated PDF (UnicodeEmojiOutput.pdf)
        // and verify that the emoji appears correctly.
        Console.WriteLine($"PDF saved to '{pdfPath}'. Please open the file to verify emoji rendering.");
    }
}
